const state={academic:{},classes:{},levels:{},classMeta:{},usrah:{},rooms:{},roomMeta:{},usrahMeta:{},schedule:[],programRaw:{},programMasterRaw:{},programs:[],users:[],staff:[],students:[],featureConfig:{version:1,roles:{}},featureCatalog:[],featureRoles:[],featureDraft:new Set()};let submitAction=null;
const safeKey=v=>String(v||'').trim().replace(/[.#$\[\]/]/g,'-');
function toast(message,type=''){const el=$('toast');el.textContent=message;el.className=`toast ${type} show`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3000)}
