function openModal({eyebrow='DATA',title,body,save='Simpan',onSubmit}){$('modalEyebrow').textContent=eyebrow;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalSave').textContent=save;submitAction=onSubmit;$('modal').classList.add('show');$('modal').setAttribute('aria-hidden','false');setTimeout(()=>$('modalBody').querySelector('input,select,textarea')?.focus(),30)}
function closeModal(){$('modal').classList.remove('show');$('modal').setAttribute('aria-hidden','true');submitAction=null}
function currentView(){const q=new URLSearchParams(location.search).get('view');return['ringkasan','santri','sdm','sekolah','asrama','jadwal','program','user','fitur'].includes(q)?q:'ringkasan'}
function showView(view,push=false){document.body.classList.toggle('admin-home-view',view==='ringkasan');document.querySelectorAll('[data-view]').forEach(el=>{if(el.closest('#moduleNav'))el.classList.toggle('active',el.dataset.view===view);else if(el.classList.contains('view'))el.classList.toggle('active',el.dataset.view===view)});if(push){const url=new URL(location.href);url.searchParams.set('view',view);history.replaceState(null,'',url)}}
function profileRoles(user){const source=Array.isArray(user.roles)?user.roles:(Array.isArray(user.role)?user.role:[user.role||user.jabatan].filter(Boolean));return source.map(value=>typeof value==='object'?(value.role||value.roleId||value.id||''):value).filter(Boolean).map(v=>String(v).toUpperCase().replace(/[ -]+/g,'_'))}
