function featureRegistry(){try{return window.parent?.CahayaFeatureManagementRegistry?.snapshot?.()||{}}catch(_){return{}}}
function prettyRole(role){return String(role||'').replace(/[_-]+/g,' ').replace(/\b\w/g,char=>char.toUpperCase())}
function prepareFeatureManagement(){const registry=featureRegistry(),roleSet=new Set([...(registry.roles||[]),...Object.keys(registry.defaults||{}),...state.users.flatMap(profileRoles),...Object.keys(state.featureConfig.roles||{})].map(C.featureRoleKey).filter(Boolean));state.featureCatalog=(registry.features||[]).filter(item=>item?.id&&!['menu-chat','menu-chat-legacy'].includes(item.id));state.featureRoles=[...roleSet].sort((a,b)=>prettyRole(a).localeCompare(prettyRole(b),'id'));const select=$('featureRole'),previous=select?.value||'admin';if(select){select.innerHTML=state.featureRoles.map(role=>`<option value="${C.esc(role)}">${C.esc(prettyRole(role))}</option>`).join('');select.value=state.featureRoles.includes(previous)?previous:(state.featureRoles.includes('admin')?'admin':state.featureRoles[0]||'')}loadFeatureDraft()}
function defaultFeaturesForRole(role){const registry=featureRegistry(),defaults=registry.defaults||{},key=C.featureRoleKey(role),aliases={'guru-pondok':'guru','guru-pkbm':'guru','naqibah':'naqib','wali-santri':'wali','layanan-kebersihan':'layanan','media':'media-digital'},lookup=aliases[key]||key,match=Object.keys(defaults).find(item=>C.featureRoleKey(item)===lookup),fromDefault=match&&Array.isArray(defaults[match])?defaults[match]:[];if(fromDefault.length)return fromDefault;return[...new Set(state.users.filter(user=>profileRoles(user).some(item=>C.featureRoleKey(item)===key)).flatMap(user=>Array.isArray(user.allowedMenus)?user.allowedMenus:[]))]}
function lockedFeatureIds(role){const ids=['menu-home'];if(C.featureRoleKey(role)==='admin')ids.push('menu-admin-features');return ids}
function loadFeatureDraft(){const role=$('featureRole')?.value||'',rule=C.featureRule(state.featureConfig,role),menus=rule?rule.enabledMenus:defaultFeaturesForRole(role);state.featureDraft=new Set([...menus,...lockedFeatureIds(role)]);if(C.featureRoleKey(role)==='konselor'&&Number(rule?.menuSchemaVersion||0)<2)['menu-kalender-pendidikan','menu-panduan-kerja','menu-profil'].forEach(id=>state.featureDraft.add(id));state.featureReset=!rule;renderFeatures()}
function featureRowsVisible(){const query=C.norm($('featureSearch')?.value);return state.featureCatalog.filter(item=>!query||C.norm(`${item.label} ${item.group} ${item.id}`).includes(query))}
function renderFeatures(){if(!$('featureList'))return;const role=$('featureRole')?.value||'',visible=featureRowsVisible(),groups=new Map;visible.forEach(item=>{const group=item.group||'Lainnya';if(!groups.has(group))groups.set(group,[]);groups.get(group).push(item)});$('featureCount').textContent=`${state.featureDraft.size} aktif · ${visible.length} ditampilkan`;$('featureRoleNote').innerHTML=`<b>${C.esc(prettyRole(role))}</b><br>${state.featureReset?'Menggunakan konfigurasi default aplikasi.':'Memiliki konfigurasi khusus yang tersimpan.'}`;$('featureList').innerHTML=visible.length?[...groups.entries()].map(([group,items])=>`<section class="feature-group"><h3>${C.esc(group)}</h3>${items.map(item=>{const locked=lockedFeatureIds(role).includes(item.id);return`<div class="feature-item ${locked?'locked':''}"><div><b>${C.esc(item.label||item.id)}</b><small>${C.esc(item.id)}${item.route?` · ${C.esc(item.route)}`:''}${locked?' · fitur wajib':''}</small></div><label class="feature-switch"><input type="checkbox" data-feature-id="${C.esc(item.id)}" ${state.featureDraft.has(item.id)?'checked':''} ${locked?'disabled':''}><span></span></label></div>`}).join('')}</section>`).join(''):'<div class="empty">Fitur tidak ditemukan.</div>'}
async function saveFeatureRole(){const role=$('featureRole')?.value;if(!role)return;const key=C.featureRoleKey(role),roles={...(state.featureConfig.roles||{})};roles[key]={enabledMenus:[...state.featureDraft].sort(),menuSchemaVersion:2,updatedAt:new Date().toISOString(),updatedBy:JSON.parse(localStorage.getItem('cahayaCurrentUser')||'{}').username||''};await setDoc(doc(fs,'settings','feature_management'),{version:1,roles,updatedAt:serverTimestamp()},{merge:true});state.featureConfig={...state.featureConfig,version:1,roles};state.featureReset=false;try{localStorage.removeItem('cahayaFeatureManagementCache')}catch(_){}try{window.parent?.postMessage({type:'CAHAYA_FEATURE_MANAGEMENT_UPDATED',config:state.featureConfig},'*')}catch(_){}renderFeatures();toast(`Fitur untuk role ${prettyRole(role)} disimpan.`)}
async function loadAll(){loading(true);try{const refs=[PATH.academic,PATH.usrah,PATH.dorm,PATH.schedule,PATH.program,PATH.programMaster].map(path=>get(ref(db,path))),userTask=getDocs(collection(fs,'users')).catch(error=>{console.warn('Profil user tidak dapat dimuat',error);return null}),featureTask=getDoc(doc(fs,'settings','feature_management')).catch(error=>{console.warn('Konfigurasi fitur tidak dapat dimuat',error);return null});const [academic,usrah,dorm,schedule,program,programMaster,userSnap,featureSnap]=await Promise.all([...refs,userTask,featureTask]);state.academic=academic.val()||{};state.classes=state.academic.kelas||state.academic.halqah?.['Halqah Ilmiyah']||{};state.levels=state.academic.jenjang||{};state.classMeta=state.academic.kelas_meta||{};state.usrah=usrah.val()||{};const dormValue=dorm.val()||{};state.rooms=dormValue.kamar||{};state.roomMeta=dormValue.kamar_meta||{};state.usrahMeta=dormValue.usrah_meta||{};state.schedule=C.scheduleRows(schedule.val());state.programRaw=program.val()||{};state.programMasterRaw=programMaster.val()||{};resolvePrograms();state.usersAvailable=Boolean(userSnap);state.loadedAt=new Date();state.users=[];userSnap?.forEach(doc=>state.users.push({id:doc.id,...doc.data()}));state.users.sort((a,b)=>String(a.label||a.nama||a.id).localeCompare(String(b.label||b.nama||b.id),'id'));state.staff=state.users.filter(user=>{const roles=profileRoles(user);return !roles.length||roles.some(role=>!role.includes('WALI'))});state.featureConfig=featureSnap?.exists()?{version:1,roles:{},...featureSnap.data()}:{version:1,roles:{}};rebuildStudents();renderAll()}catch(error){console.error(error);$('overviewUpdated').textContent='Gagal memuat data. Silakan muat ulang.';toast(`Gagal memuat data: ${error.message}`,'error')}finally{loading(false)}}
function rebuildStudents(){state.students=C.studentRows(state.classes,state.usrah,state.rooms)}
function renderAll(){renderOverview();renderStudents();renderStaff();renderSchool();renderDorm();renderSchedule();renderPrograms();$('userSummary').innerHTML=`<span class="chip">${state.users.length} akun</span><span class="chip">${state.users.filter(x=>Number(x.roleSystemVersion)===2).length} Role V2</span>`;prepareFeatureManagement()}
function renderOverview(){
  const now=new Date(),active=state.schedule.filter(row=>row.aktif!==false),total=state.students.length;
  $('overviewDate').textContent=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);
  $('overviewUpdated').textContent=state.loadedAt?`Data dimuat pukul ${new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit'}).format(state.loadedAt)}`:'Menunggu data…';
  const classes=allClassNames().filter(name=>!/^PKBM/i.test(name)),usrahNames=Object.keys(C.rosters(state.usrah)),roomNames=Object.keys(C.rosters(state.rooms));
  const metrics=[{value:total,label:'Total Santri',note:'Santri unik pada roster',view:'santri'},{value:classes.filter(name=>/putra/i.test(name)).length,label:'Kelas Putra',note:'Kepondokan',view:'sekolah'},{value:classes.filter(name=>/putri/i.test(name)).length,label:'Kelas Putri',note:'Kepondokan',view:'sekolah'},{value:usrahNames.length,label:'Usrah Terdata',note:'Kelompok pendampingan',view:'asrama'},{value:roomNames.length,label:'Kamar Terdata',note:'Penempatan asrama',view:'asrama'}];
  renderOverviewCharts(classes);
  $('overviewMetrics').innerHTML=metrics.map(item=>`<button class="overview-metric" data-view="${item.view}"><span>${item.label}<span aria-hidden="true">↗</span></span><b>${C.esc(item.value)}</b><small>${item.note}</small></button>`).join('');
  const today=active.filter(row=>scheduleDay(row)===now.getDay()).sort((a,b)=>String(a.jamMulai||'99:99').localeCompare(String(b.jamMulai||'99:99'))||String(a.kelas||'').localeCompare(String(b.kelas||''),'id',{numeric:true}));
  $('overviewScheduleSummary').textContent=`${today.length} sesi aktif${today.length>6?' · Menampilkan 6 sesi pertama':''}`;
  $('overviewSchedule').innerHTML=today.length?today.slice(0,6).map(row=>`<div class="overview-session"><div class="overview-time"><b>${C.esc(row.jamMulai||row.waktuLabel||'Belum diatur')}</b><small>${C.esc(row.jamSelesai||'')}</small></div><div><b>${C.esc(row.mapel||row.mataPelajaran||'Mapel belum diatur')}</b><small>${C.esc(scheduleTeacher(row))}</small></div><span class="tag">${C.esc(row.kelas||'Kelas belum diatur')}</span></div>`).join(''):'<div class="overview-empty">Tidak ada sesi pelajaran aktif untuk hari ini.<br><button class="btn small" data-view="jadwal">Lihat jadwal sepekan</button></div>';
  const missing=field=>state.students.filter(student=>!student[field]?.length).length;
  const issues=[{count:missing('kelas'),label:'Santri belum memiliki kelas',view:'santri'},{count:missing('usrah'),label:'Santri belum memiliki usrah',view:'asrama'},{count:missing('kamar'),label:'Santri belum memiliki kamar',view:'asrama'},{count:active.filter(row=>![row.guruNama,row.namaGuru,row.guruKode,row.guruId,row.guru].some(Boolean)).length,label:'Sesi belum memiliki guru',view:'jadwal'},{count:state.usersAvailable===false?0:state.users.filter(user=>user.active!==false&&!profileRoles(user).length).length,label:'Akun aktif belum memiliki role',view:'user'}].filter(item=>item.count);
  $('overviewAttention').innerHTML=(state.usersAvailable===false?'<p class="overview-warning">Data akun belum tersedia. Muat ulang untuk memeriksa role pengguna.</p>':'')+(issues.length?issues.map(item=>`<button class="overview-issue" data-view="${item.view}"><b>${item.count}</b><span>${item.label}</span><span aria-hidden="true">→</span></button>`).join(''):`<div class="overview-empty">${total?'Penempatan dan penugasan yang diperiksa sudah lengkap.':'Belum ada data santri untuk diperiksa.'}</div>`);
  $('overviewCoverage').innerHTML=[['kelas','Kelas'],['usrah','Usrah'],['kamar','Kamar']].map(([key,label])=>{const assigned=total-missing(key),percent=total?Math.round(assigned/total*100):0;return `<div class="overview-progress"><div><b>${label}</b><span>${assigned} / ${total} santri</span></div><progress value="${assigned}" max="${total||1}" aria-label="Penempatan ${label}: ${percent}%"></progress></div>`}).join('');
}
function renderOverviewCharts(classes){
  const palette=['#216bbb','#e7a72f','#79afe2','#163c6c','#f4ce74','#4389cf','#b57a1b'];
  const bars=classes.map(name=>({name,count:C.names(state.classes[name]).length})),max=Math.max(1,...bars.map(row=>row.count));
  $('overviewClassChart').innerHTML=bars.length?`<div class="overview-bars" role="img" aria-label="${C.esc(bars.map(row=>`${row.name}: ${row.count} santri`).join('; '))}">${bars.map(row=>`<div class="overview-bar-col"><b>${row.count}</b><div class="overview-bar-track"><span style="height:${row.count/max*100}%;background:${/putri/i.test(row.name)?'#e7a72f':'#2676c7'}"></span></div><span title="${C.esc(row.name)}">${C.esc(row.name.replace(/Kelas /i,'').replace(/Putra/i,'P').replace(/Putri/i,'Q').replace(/\s+/g,''))}</span></div>`).join('')}</div><div class="overview-chart-legend"><span>● Putra</span><span>● Putri</span></div>`:'<div class="overview-empty">Belum ada data kelas.</div>';
  const buckets=new Map();state.students.forEach(student=>{const groups=[...new Set(student.usrah||[])];const label=groups.length>1?'Beberapa usrah':groups[0]||'Belum ditempatkan';buckets.set(label,(buckets.get(label)||0)+1)});
  const distribution=[...buckets].sort((a,b)=>b[1]-a[1]),total=state.students.length;let offset=0;
  const stops=distribution.map(([name,count],index)=>{const start=offset;offset+=count/(total||1)*100;return `${palette[index%palette.length]} ${start}% ${offset}%`});
  $('overviewUsrahChart').innerHTML=total?`<div class="overview-donut-layout"><div class="overview-donut" style="background:conic-gradient(${stops.join(',')})" role="img" aria-label="${C.esc(distribution.map(([name,count])=>`${name}: ${count}`).join('; '))}"><div><b>${total}</b><span>Santri</span></div></div><div class="overview-donut-legend">${distribution.map(([name,count],i)=>`<div><i style="background:${palette[i%palette.length]}"></i><span>${C.esc(name)}</span><b>${count}</b></div>`).join('')}</div></div>`:'<div class="overview-empty">Belum ada data santri.</div>';
  const staff=state.staff.filter(user=>user.active!==false&&user.disabled!==true),categories=[['Guru',roles=>roles.some(role=>role.startsWith('GURU'))],['Naqib / Naqibah',roles=>roles.some(role=>['NAQIB','NAQIBAH'].includes(role))],['Konselor',roles=>roles.includes('KONSELOR')]];
  const staffCounts=categories.map(([label,test])=>[label,staff.filter(user=>test(profileRoles(user))).length]);staffCounts.push(['Lainnya',staff.filter(user=>!categories.some(([,test])=>test(profileRoles(user)))).length]);
  $('overviewStaff').innerHTML=state.usersAvailable===false?'<div class="overview-empty">Data SDM belum dapat dimuat.</div>':`<div class="overview-staff-total"><span>♙</span><div><b>${staff.length}</b><small>Personel aktif</small></div></div>${staffCounts.map(([label,count])=>`<div class="overview-staff-row"><span>${C.esc(label)}</span><b>${count}</b></div>`).join('')}<p class="overview-footnote">Satu personel dapat memiliki beberapa role.</p>`;
  const stamp=value=>{if(value?.seconds)return value.seconds*1000;if(value?._seconds)return value._seconds*1000;return typeof value==='number'?value:Date.parse(value||'')};
  const updates=[...state.schedule.map(row=>({label:`Jadwal ${row.mapel||'pelajaran'} · ${row.kelas||''}`,time:stamp(row.waktuUpdate||row.updatedAt),view:'jadwal'})),...state.users.map(user=>({label:`Profil ${user.label||user.nama||user.username||'pengguna'}`,time:stamp(user.updatedAt||user.createdAt),view:'user'})),...state.programs.map(row=>({label:`Program ${row.nama}`,time:stamp(row.updatedAt),view:'program'}))].filter(row=>Number.isFinite(row.time)&&row.time>0).sort((a,b)=>b.time-a.time).slice(0,5);
  $('overviewActivity').innerHTML=updates.length?updates.map(row=>`<button class="overview-update" data-view="${row.view}"><span class="overview-update-dot"></span><span><b>${C.esc(row.label)}</b><small>${C.esc(new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(row.time))} WIB</small></span><span>↗</span></button>`).join(''):'<div class="overview-empty">Belum ada waktu pembaruan yang tercatat.</div>';
}
function renderStudents(){const query=C.norm($('studentSearch')?.value),rows=state.students.filter(s=>!query||C.norm([s.nama,...s.kelas,...s.usrah,...s.kamar].join(' ')).includes(query));$('studentCount').textContent=`${rows.length} dari ${state.students.length} santri`;$('studentStats').innerHTML=stat(state.students.length,'Santri terdata')+stat(Object.keys(C.rosters(state.classes)).length,'Kelas aktif')+stat(Object.keys(C.rosters(state.usrah)).length,'Usrah aktif')+stat(Object.keys(C.rosters(state.rooms)).length,'Kamar terdata');$('studentRows').innerHTML=rows.length?rows.map(s=>`<tr><td><b>${C.esc(s.nama)}</b><br><span class="muted">${C.esc(s.studentKey)}</span></td><td>${s.kelas.map(x=>tag(x)).join('')||tag('')}</td><td>${s.usrah.map(x=>tag(x,'warn')).join('')||tag('')}</td><td>${s.kamar.map(x=>tag(x,'gray')).join('')||tag('')}</td><td><div class="row-actions"><button class="icon-btn" data-edit-student="${C.esc(s.studentKey)}" title="Ubah">✎</button><button class="icon-btn" data-delete-student="${C.esc(s.studentKey)}" title="Hapus">×</button></div></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Santri tidak ditemukan.</td></tr>'}
function renderStaff(){const query=C.norm($('staffSearch')?.value),rows=state.staff.filter(s=>!query||C.norm(`${s.label||s.nama||''} ${s.username||s.id} ${profileRoles(s).join(' ')}`).includes(query)),roles=new Set(state.staff.flatMap(profileRoles));$('staffCount').textContent=`${rows.length} dari ${state.staff.length} personel`;$('staffStats').innerHTML=stat(state.staff.length,'Profil SDM')+stat(roles.size,'Jenis role')+stat(state.staff.filter(x=>x.active!==false).length,'Akun aktif')+stat(state.staff.filter(x=>Number(x.roleSystemVersion)===2).length,'Profil Role V2');$('staffRows').innerHTML=rows.length?rows.map(s=>`<tr><td><b>${C.esc(s.label||s.nama||s.username||s.id)}</b></td><td>@${C.esc(s.username||s.id)}</td><td>${profileRoles(s).map(x=>tag(x.replaceAll('_',' '))).join('')||tag('')}</td><td>${tag(s.active===false?'Nonaktif':'Aktif',s.active===false?'gray':'green')}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">Data SDM tidak ditemukan.</td></tr>'}
function levelRows(){const rows=Object.entries(state.levels||{}).map(([id,v])=>typeof v==='string'?{id,nama:v}:{id,nama:v?.nama||v?.label||id,unit:v?.unit||''});if(!rows.length)[...new Set(Object.keys(state.classes).map(C.inferLevel))].forEach(nama=>rows.push({id:C.slug(nama),nama,unit:''}));return rows.sort((a,b)=>a.nama.localeCompare(b.nama,'id'))}
