function renderSchool(){const levels=levelRows();$('levelList').innerHTML=levels.length?levels.map(x=>`<div class="manage-item"><div><b>${C.esc(x.nama)}</b><small>${C.esc(x.unit||'Jenjang aktif')}</small></div><div class="row-actions"><button class="icon-btn" data-edit-level="${C.esc(x.id)}">✎</button><button class="icon-btn" data-delete-level="${C.esc(x.id)}">×</button></div></div>`).join(''):'<div class="empty">Belum ada jenjang.</div>';$('classList').innerHTML=allClassNames().map(name=>{const count=C.names(state.classes[name]).length,meta=state.classMeta[name]||{};return`<div class="manage-item"><div><b>${C.esc(name)}</b><small>${C.esc(meta.jenjang||C.inferLevel(name))} · ${count} peserta</small></div><div class="row-actions"><button class="btn small" data-members="kelas" data-group="${C.esc(name)}">Peserta</button><button class="icon-btn" data-edit-class="${C.esc(name)}">✎</button><button class="icon-btn" data-delete-class="${C.esc(name)}">×</button></div></div>`}).join('')||'<div class="empty">Belum ada kelas.</div>'}
function renderDorm(){const roomNames=[...new Set([...Object.keys(C.rosters(state.rooms)),...Object.keys(state.roomMeta||{})])].sort((a,b)=>a.localeCompare(b,'id',{numeric:true})),usrahNames=[...new Set([...Object.keys(C.rosters(state.usrah)),...Object.keys(state.usrahMeta||{})])].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));$('roomList').innerHTML=groupItems(roomNames,'kamar',state.rooms);$('usrahList').innerHTML=groupItems(usrahNames,'usrah',state.usrah)}
function groupItems(items,type,source){return items.length?items.map(name=>`<div class="manage-item"><div><b>${C.esc(name)}</b><small>${C.names(source[name]).length} anggota</small></div><div class="row-actions"><button class="btn small" data-members="${type}" data-group="${C.esc(name)}">Anggota</button><button class="icon-btn" data-edit-group="${type}" data-group="${C.esc(name)}">✎</button><button class="icon-btn" data-delete-group="${type}" data-group="${C.esc(name)}">×</button></div></div>`).join(''):'<div class="empty">Belum ada data.</div>'}
const SCHEDULE_DAYS=['Ahad','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
function scheduleDay(row){
  const raw=String(row.hari??row.hariLabel??'').trim();
  if(/^[0-6]$/.test(raw))return Number(raw);
  const label=C.norm(raw).replace(/[’']/g,'');
  return label==='minggu'?0:SCHEDULE_DAYS.findIndex(day=>C.norm(day)===label);
}
function scheduleTeacher(row){
  const keys=[row.guruId,row.guruKode,row.guruNama,row.guru].filter(Boolean).map(C.norm);
  const matches=state.users.filter(user=>[user.id,user.uid,user.username,user.teacherCode,user.guruKode,user.kodeGuru,user.nama,user.label,user.displayName].filter(Boolean).some(value=>keys.includes(C.norm(value))));
  const user=matches.length===1?matches[0]:null;
  return user?.namaLengkap||user?.fullName||user?.nama||user?.displayName||user?.label||row.guruNama||row.namaGuru||row.guru||row.guruKode||row.guruId||'Guru belum ditentukan';
}
function scheduleGroup(row){
  const text=`${row.unit||''} ${row.kelas||''}`,pkbm=/pkbm/i.test(text)||row.jenis==='pkbm';
  return `${pkbm?'PKBM · ':''}${/putri/i.test(text)?'Putri':/putra/i.test(text)?'Putra':'Kelas Gabungan'}`;
}
function scheduleIcon(kind='book'){
  const paths={book:'<path d="M12 5C8 3 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-5-1-9 1Zm0 0v15M6 8h3M6 11h3M15 8h3M15 11h3"/>',quran:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M5 17h14M12 6l3 4-3 4-3-4Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h3M14 14h3M7 17h3"/>',people:'<circle cx="12" cy="7" r="3"/><path d="M6 21v-3a6 6 0 0 1 12 0v3M5 5a3 3 0 0 0 0 6M19 5a3 3 0 0 1 0 6M2 19v-3a4 4 0 0 1 3-4M22 19v-3a4 4 0 0 0-3-4"/>'};
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.book}</svg>`;
}
function filteredSchedule(){const query=C.norm($('scheduleSearch').value),selected=$('scheduleClass').value;return state.schedule.filter(row=>(!selected||row.kelas===selected)&&(!query||C.norm([row.mapel||row.mataPelajaran,scheduleTeacher(row),row.guruKode,row.kelas,row.hariLabel,SCHEDULE_DAYS[scheduleDay(row)]].join(' ')).includes(query)))}
function scheduleSubject(row){
  const subject=row.mapel||row.mataPelajaran||'Mapel belum ditentukan',time=row.jamMulai?[row.jamMulai,row.jamSelesai].filter(Boolean).join('–'):(row.waktuLabel||'');
  const quran=/qur/i.test(subject),arab=/arab/i.test(subject),tone=quran?'green':arab?'blue':'amber';
  return `<div class="poster-subject${row.aktif===false?' inactive':''}"><span class="lesson-icon ${tone}">${scheduleIcon(quran?'quran':'book')}</span><div class="lesson-content"><b>${C.esc(subject)}</b> <span>(${C.esc(scheduleTeacher(row))})</span>${time?`<small>${C.esc(time)}</small>`:''}${row.aktif===false?'<small>Nonaktif</small>':''}</div></div>`;
}
function renderSchedule(){
  const active=state.schedule.filter(x=>x.aktif!==false),pkbm=active.filter(x=>/pkbm/i.test(`${x.jenis||''} ${x.sesi||''} ${x.unit||''} ${x.kelas||''}`)),teachers=new Set(active.map(scheduleTeacher).filter(x=>x!=='Guru belum ditentukan'));
  $('scheduleStats').innerHTML=stat(active.length,'Sesi aktif')+stat(active.length-pkbm.length,'Kepondokan')+stat(pkbm.length,'PKBM')+stat(teachers.size,'Guru terjadwal');
  const select=$('scheduleClass'),previous=select.value,classes=[...new Set(state.schedule.map(x=>x.kelas).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));
  select.innerHTML=options(classes,previous,'Semua kelas');
  const selected=select.value,visible=filteredSchedule();
  $('scheduleCount').textContent=`${visible.length} dari ${state.schedule.length} sesi${selected?' · '+selected:''}`;
  const groups=['Putra','Putri','Kelas Gabungan','PKBM · Putra','PKBM · Putri','PKBM · Kelas Gabungan'];
  $('scheduleDays').innerHTML=visible.length?groups.map(group=>{
    const grouped=visible.filter(row=>scheduleGroup(row)===group);
    if(!grouped.length)return '';
    const classNames=[...new Set(grouped.map(row=>row.kelas||'Kelas belum ditentukan'))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));
    return `<section class="poster-group ${group.includes('Putri')?'poster-putri':''}"><header class="poster-group-head"><div class="unit-heading"><span class="unit-icon">${scheduleIcon("people")}</span><div><h3>${C.esc(group)}</h3><p>Jadwal pelajaran ${C.esc(group.toLowerCase())} per kelas</p></div></div><div class="unit-download-actions"><span class="unit-count">${classNames.length} kelas · ${grouped.length} sesi</span><button type="button" class="btn small" data-download-group="${C.esc(group)}">↓ Download ${C.esc(group)}</button></div></header><div class="poster-classes" tabindex="0" role="region" aria-label="Jadwal kelas ${C.esc(group)}, geser untuk melihat kelas lainnya">${classNames.map(name=>{
      const sessions=grouped.filter(row=>(row.kelas||'Kelas belum ditentukan')===name).sort((a,b)=>String(a.jamMulai||'99:99').localeCompare(String(b.jamMulai||'99:99')));
      const days=[1,2,3,4,5,6,0,-1];
      return `<article class="poster-class"><header><span class="class-icon">${scheduleIcon("people")}</span><div><span>KELAS</span><h4>${C.esc(name.replace(/^Kelas\s+/i,''))}</h4></div><button type="button" class="class-download" data-download-class="${C.esc(name)}" data-download-group="${C.esc(group)}" aria-label="Download jadwal ${C.esc(name)}" title="Download jadwal kelas">↓</button></header><div class="poster-week">${days.map(day=>{
        const lessons=sessions.filter(row=>scheduleDay(row)===day);
        return lessons.length?`<div class="poster-day"><h5>${scheduleIcon("calendar")}${day===-1?'Hari belum diatur':SCHEDULE_DAYS[day]}</h5><div>${lessons.map(scheduleSubject).join('')}</div></div>`:'';
      }).join('')}</div></article>`;
    }).join('')}</div></section>`;
  }).join(''):'<div class="empty card">Tidak ada jadwal yang sesuai.</div>';

}

async function downloadSchedule({group='',kelas='',button=$('downloadSchedule')}={}){
  const rows=filteredSchedule().filter(row=>(!group||scheduleGroup(row)===group)&&(!kelas||(row.kelas||'Kelas belum ditentukan')===kelas));
  if(!rows.length)return toast('Tidak ada jadwal untuk diunduh.','error');
  const previousLabel=button.textContent;button.disabled=true;button.textContent='…';
  const exportedAt=new Date(),query=$('scheduleSearch').value.trim(),selected=$('scheduleClass').value;
  try{
    await document.fonts.ready;
    const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),gap=24,pad=44;
    const groups=['Putra','Putri','Kelas Gabungan','PKBM · Putra','PKBM · Putri','PKBM · Kelas Gabungan'].map(name=>({name,rows:rows.filter(row=>scheduleGroup(row)===name)})).filter(item=>item.rows.length);
    const columnCount=Math.max(...groups.map(item=>new Set(item.rows.map(row=>row.kelas||'Kelas belum ditentukan')).size));
    const columnWidth=columnCount===1?440:300,width=pad*2+columnCount*(columnWidth+gap)-gap;
    const wrap=(text,maxWidth)=>{const lines=[];let line='';for(const word of String(text).split(/\s+/)){const next=line?line+' '+word:word;if(ctx.measureText(next).width<=maxWidth){line=next;continue}if(line)lines.push(line);line='';for(const char of word){if(ctx.measureText(line+char).width>maxWidth&&line){lines.push(line);line=''}line+=char}}if(line)lines.push(line);return lines};
    const app=window.CAHAYA_CONFIG?.app||{},scope=kelas||group||selected||'Seluruh kelas';
    const years=[...new Set(rows.map(row=>row.tahunAjaran).filter(Boolean))];
    const academicYear=years.join(', ')||app.academicYear||'—';
    ctx.font='bold 22px sans-serif';const institutionLines=wrap(app.institutionName||'CAHAYA APP',width-pad*2);
    ctx.font='18px sans-serif';const subtitleLines=wrap(`${scope} · Tahun ajaran ${academicYear} · ${rows.length} sesi`,width-pad*2);
    ctx.font='14px sans-serif';const filterLines=query?wrap(`Hasil pencarian: ${query}`,width-pad*2):[];
    const headerHeight=164+institutionLines.length*29+subtitleLines.length*26+filterLines.length*21;
    const stamp=new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(exportedAt);
    const footerLines=wrap(`Diunduh dari CAHAYA APP pada ${stamp} WIB.`,width-pad*2);
    const noteLines=wrap('Dokumen jadwal pembelajaran · Data sesuai jadwal yang ditampilkan saat diunduh.',width-pad*2);
    const footerHeight=70+(footerLines.length+noteLines.length)*22;
    const layouts=groups.map(item=>{
      const names=[...new Set(item.rows.map(row=>row.kelas||'Kelas belum ditentukan'))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));
      const cards=names.map(name=>{
        ctx.font='bold 19px sans-serif';const titleLines=wrap(name.replace(/^Kelas\s+/i,''),columnWidth-86),titleHeight=48+titleLines.length*26;
        let y=titleHeight+42;const entries=[];
        for(const day of [1,2,3,4,5,6,0,-1]){
          const lessons=item.rows.filter(row=>(row.kelas||'Kelas belum ditentukan')===name&&scheduleDay(row)===day).sort((a,b)=>String(a.jamMulai||'99:99').localeCompare(String(b.jamMulai||'99:99')));
          if(!lessons.length)continue;
          entries.push({y,day:day===-1?'Hari belum diatur':SCHEDULE_DAYS[day]});y+=32;
          for(const row of lessons){
            const subject=row.mapel||row.mataPelajaran||'Mapel';
            ctx.font='bold 15px sans-serif';const lines=wrap(`${subject} (${scheduleTeacher(row)})`,columnWidth-78);
            const time=row.jamMulai?[row.jamMulai,row.jamSelesai].filter(Boolean).join(' – '):(row.waktuLabel||'Jam belum diatur');
            ctx.font='13px sans-serif';const timeLines=wrap(time+(row.aktif===false?' · Nonaktif':''),columnWidth-78);
            const boxHeight=lines.length*23+timeLines.length*20+24;entries.push({y,lines,timeLines,boxHeight,subject});y+=boxHeight+14;
          }y+=15;
        }
        return{name,titleLines,titleHeight,entries,height:y+12};
      });return{name:item.name,cards,height:Math.max(...cards.map(card=>card.height))+126};
    });
    const height=headerHeight+layouts.reduce((n,item)=>n+item.height+26,0)+footerHeight;
    if(width>30000||height>30000||width*height>50000000)throw new Error('Jadwal terlalu besar. Unduh per kelas atau kelompok.');
    const scale=Math.min(2,Math.sqrt(50000000/(width*height)),30000/height,30000/width);
    canvas.width=Math.floor(width*scale);canvas.height=Math.floor(height*scale);ctx.scale(scale,scale);
    const rounded=(x,y,w,h,r,fill)=>{ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill()};
    const icon=(kind,x,y,size,color)=>{
      ctx.save();ctx.translate(x,y);ctx.scale(size/24,size/24);ctx.strokeStyle=color;ctx.lineWidth=1.7;ctx.lineCap='round';ctx.lineJoin='round';
      const svg=scheduleIcon(kind);
      for(const match of svg.matchAll(/<path d="([^"]+)"/g))ctx.stroke(new Path2D(match[1]));
      for(const match of svg.matchAll(/<(rect|circle) ([^>]+)\/>/g)){
        const attrs=Object.fromEntries([...match[2].matchAll(/(\w+)="([^"]+)"/g)].map(m=>[m[1],Number(m[2])]));ctx.beginPath();
        if(match[1]==='rect')ctx.roundRect(attrs.x,attrs.y,attrs.width,attrs.height,attrs.rx||0);else ctx.arc(attrs.cx,attrs.cy,attrs.r,0,Math.PI*2);ctx.stroke();
      }ctx.restore();
    };
    const circle=(x,y,r,fill)=>{ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill()};
    ctx.fillStyle='#f4f8ff';ctx.fillRect(0,0,width,height);
    const headerGradient=ctx.createLinearGradient(0,0,width,headerHeight);headerGradient.addColorStop(0,'#fffdf7');headerGradient.addColorStop(1,'#eaf4ff');
    rounded(20,20,width-40,headerHeight-42,22,headerGradient);
    let hy=54;ctx.fillStyle='#507798';ctx.font='bold 11px sans-serif';ctx.fillText('ADMINISTRASI AKADEMIK  /  CAHAYA APP',pad,hy);hy+=44;
    ctx.fillStyle='#102e55';ctx.font='bold 30px Georgia, serif';ctx.fillText('JADWAL PELAJARAN',pad,hy);hy+=38;
    ctx.font='bold 22px sans-serif';institutionLines.forEach(line=>{ctx.fillText(line,pad,hy);hy+=29});
    ctx.fillStyle='#59708b';ctx.font='18px sans-serif';subtitleLines.forEach(line=>{ctx.fillText(line,pad,hy);hy+=26});
    ctx.font='14px sans-serif';filterLines.forEach(line=>{ctx.fillText(line,pad,hy);hy+=21});
    let top=headerHeight;
    for(const item of layouts){
      rounded(20,top,width-40,item.height+10,24,'#fff');
      circle(pad+25,top+38,25,item.name.includes('Putri')?'#fceaf3':'#e4f7f1');icon('people',pad+11,top+24,28,item.name.includes('Putri')?'#b43a79':'#147969');
      ctx.fillStyle='#102951';ctx.font='bold 28px Georgia, serif';ctx.fillText(item.name,pad+66,top+35);
      ctx.font='13px sans-serif';ctx.fillStyle='#7588a2';ctx.fillText(`Jadwal pelajaran ${item.name.toLowerCase()} per kelas`,pad+66,top+58);
      const commonHeight=Math.max(...item.cards.map(card=>card.height));
      item.cards.forEach((card,index)=>{
        const x=pad+index*(columnWidth+gap),y=top+94;
        ctx.save();ctx.shadowColor='#152c4110';ctx.shadowBlur=16;ctx.shadowOffsetY=5;rounded(x,y,columnWidth,commonHeight,16,'#ffffff');ctx.restore();
        const palettes=[['#eaf9f4','#087365'],['#eaf5ff','#0978ad'],['#fff7e7','#ae7b16'],['#f3efff','#6650b4'],['#e8f8f9','#138487']];
        const originalClasses=[...new Set(state.schedule.filter(row=>scheduleGroup(row)===item.name).map(row=>row.kelas||'Kelas belum ditentukan'))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));
        const [tint,accent]=palettes[Math.max(0,originalClasses.indexOf(card.name))%palettes.length];
        ctx.save();ctx.beginPath();ctx.roundRect(x,y,columnWidth,commonHeight,16);ctx.clip();ctx.fillStyle=tint;ctx.fillRect(x,y,columnWidth,card.titleHeight);ctx.restore();
        ctx.strokeStyle='#dceafb';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(x,y,columnWidth,commonHeight,16);ctx.stroke();
        circle(x+35,y+card.titleHeight/2,19,'#ffffffb8');icon('people',x+23,y+card.titleHeight/2-12,24,accent);
        ctx.fillStyle=accent;ctx.font='11px sans-serif';ctx.fillText('KELAS',x+66,y+25);
        ctx.fillStyle='#12335b';ctx.font='bold 19px sans-serif';card.titleLines.forEach((line,i)=>ctx.fillText(line,x+66,y+49+i*26));
        for(const entry of card.entries){
          if(entry.day){
            if(entry!==card.entries[0]){ctx.fillStyle='#edf1f4';ctx.fillRect(x+18,y+entry.y-28,columnWidth-36,1)}
            icon('calendar',x+18,y+entry.y-15,18,'#008ccc');
            ctx.fillStyle='#174774';ctx.font='bold 15px sans-serif';ctx.fillText(entry.day,x+46,y+entry.y);
          }else{
            const quran=/qur/i.test(entry.subject),arab=/arab/i.test(entry.subject),tint=quran?'#e1f7ee':arab?'#e5f5ff':'#fff4dc',accent=quran?'#07865d':arab?'#008bc9':'#af7d16';
            circle(x+32,y+entry.y+2,16,tint);icon(quran?'quran':'book',x+23,y+entry.y-7,18,accent);
            let remaining=entry.subject.length;
            entry.lines.forEach((line,i)=>{
              const count=Math.min(remaining,line.length),bold=line.slice(0,count),plain=line.slice(count);let tx=x+58;
              ctx.fillStyle='#16365b';ctx.font='bold 15px sans-serif';if(bold){ctx.fillText(bold,tx,y+entry.y+i*23);tx+=ctx.measureText(bold).width}
              ctx.fillStyle='#405774';ctx.font='15px sans-serif';if(plain)ctx.fillText(plain,tx,y+entry.y+i*23);remaining=Math.max(0,remaining-line.length-1);
            });
            ctx.fillStyle='#7b90ac';ctx.font='13px sans-serif';entry.timeLines.forEach((line,i)=>ctx.fillText(line,x+58,y+entry.y+entry.lines.length*23+5+i*20));
          }
        }
      });top+=item.height+26;
    }
    ctx.fillStyle='#d9d9d2';ctx.fillRect(pad,top+4,width-pad*2,1);
    let fy=top+38;ctx.font='14px sans-serif';ctx.fillStyle='#41576a';footerLines.forEach(line=>{ctx.fillText(line,pad,fy);fy+=22});
    ctx.fillStyle='#85919a';noteLines.forEach(line=>{ctx.fillText(line,pad,fy);fy+=22});
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('Gambar gagal dibuat. Coba unduh satu kelas.');
    const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;
    const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(exportedAt);
    link.download=`jadwal-pelajaran-${C.slug(scope)}-${date}.png`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Jadwal PNG siap diunduh.');
  }catch(error){toast(error.message||'Download gagal.','error')}finally{button.disabled=false;button.textContent=previousLabel}
}

function renderPrograms(){const query=C.norm($('programSearch')?.value),rows=state.programs.filter(p=>!query||C.norm(`${p.nama} ${p.kategori} ${p.mulai} ${p.selesai}`).includes(query));$('programCount').textContent=`${rows.length} dari ${state.programs.length} program`;$('programStats').innerHTML=stat(state.programs.filter(x=>x.aktif).length,'Program aktif')+stat(state.programs.filter(x=>x.wajibAbsen).length,'Wajib diabsen')+stat(state.programs.filter(x=>x.wajibLaporan).length,'Wajib dilaporkan')+stat(new Set(state.programs.map(x=>x.kategori)).size,'Kategori');$('programList').innerHTML=rows.length?rows.map(p=>`<article class="program-card"><header><div><h4>${C.esc(p.nama)}</h4><span class="muted">${C.esc(p.kategori)}</span></div><div class="row-actions"><button class="icon-btn" data-edit-program="${C.esc(p.id)}">✎</button><button class="icon-btn" data-delete-program="${C.esc(p.id)}">×</button></div></header><div class="program-meta"><b>${C.esc(p.mulai||'--:--')} – ${C.esc(p.selesai||'--:--')}</b><br><span class="muted">${C.esc(p.hariAktif.length?p.hariAktif.join(', '):'Setiap hari')}</span></div><div class="flags">${tag(p.aktif?'Aktif':'Nonaktif',p.aktif?'green':'gray')}${p.wajibAbsen?tag('Wajib Absen'):tag('Tanpa Absensi','gray')}${p.wajibLaporan?tag('Wajib Laporan','warn'):tag('Tanpa Laporan','gray')}</div></article>`).join(''):'<div class="empty">Program tidak ditemukan.</div>'}
function studentForm(row={}){const classes=allClassNames(),usrahs=[...new Set([...Object.keys(C.rosters(state.usrah)),...Object.keys(state.usrahMeta)])].sort(),rooms=[...new Set([...Object.keys(C.rosters(state.rooms)),...Object.keys(state.roomMeta)])].sort();return`<input type="hidden" id="fOriginal" value="${C.esc(row.nama||'')}"><div class="field full"><label>Nama lengkap santri</label><input id="fName" value="${C.esc(row.nama||'')}" required placeholder="Nama sesuai data resmi"></div><div class="field"><label>Kelas akademik</label><select id="fClass">${options(classes,row.kelas?.[0]||'')}</select></div><div class="field"><label>Usrah / halaqah</label><select id="fUsrah">${options(usrahs,row.usrah?.[0]||'')}</select></div><div class="field"><label>Kamar</label><select id="fRoom">${options(rooms,row.kamar?.[0]||'')}</select></div><div class="field full help">Penempatan diperbarui pada roster yang sudah dipakai modul absensi dan laporan. Nama tidak diubah menjadi struktur baru agar data lama tetap kompatibel.</div>`}
function openStudent(row={}){openModal({eyebrow:'DATA SANTRI',title:row.nama?'Ubah Data Santri':'Tambah Santri',body:studentForm(row),onSubmit:saveStudent})}
async function saveStudent(){const old=$('fOriginal').value.trim(),name=$('fName').value.trim().toUpperCase(),kelas=$('fClass').value,usrah=$('fUsrah').value,kamar=$('fRoom').value;if(!name)throw new Error('Nama santri wajib diisi.');const duplicate=state.students.find(x=>C.norm(x.nama)===C.norm(name)&&C.norm(x.nama)!==C.norm(old));if(duplicate)throw new Error('Nama santri tersebut sudah terdaftar.');const classNext=C.replaceMember(state.classes,old,name,kelas),usrahNext=C.replaceMember(state.usrah,old,name,usrah),roomNext=C.replaceMember(state.rooms,old,name,kamar);await update(ref(db),{[PATH.classes]:classNext,[PATH.usrah]:usrahNext,[PATH.rooms]:roomNext});state.classes=classNext;state.usrah=usrahNext;state.rooms=roomNext;rebuildStudents();renderStudents();renderSchool();renderDorm();closeModal();toast('Data santri tersimpan.')}
async function deleteStudent(row){if(!confirm(`Hapus ${row.nama} dari seluruh roster kelas, usrah, dan kamar? Data nilai/riwayat tidak dihapus.`))return;const classNext=C.replaceMember(state.classes,row.nama,'',''),usrahNext=C.replaceMember(state.usrah,row.nama,'',''),roomNext=C.replaceMember(state.rooms,row.nama,'','');await update(ref(db),{[PATH.classes]:classNext,[PATH.usrah]:usrahNext,[PATH.rooms]:roomNext});state.classes=classNext;state.usrah=usrahNext;state.rooms=roomNext;rebuildStudents();renderAll();toast('Santri dihapus dari roster aktif.')}
function openLevel(item={}){openModal({eyebrow:'DATA SEKOLAH',title:item.nama?'Ubah Jenjang':'Tambah Jenjang',body:`<input type="hidden" id="fId" value="${C.esc(item.id||'')}"><div class="field full"><label>Nama jenjang</label><input id="fName" required value="${C.esc(item.nama||'')}" placeholder="Contoh: PKBM SMP"></div><div class="field full"><label>Unit / keterangan</label><input id="fUnit" value="${C.esc(item.unit||'')}" placeholder="Putra, Putri, atau Semua"></div>`,onSubmit:async()=>{const old=$('fId').value,id=old||C.slug($('fName').value),data={nama:$('fName').value.trim(),unit:$('fUnit').value.trim(),aktif:true,updatedAt:new Date().toISOString()};if(!data.nama)throw new Error('Nama jenjang wajib diisi.');if(old&&old!==id)await remove(ref(db,`${PATH.levels}/${safeKey(old)}`));await set(ref(db,`${PATH.levels}/${safeKey(id)}`),data);state.levels[id]=data;closeModal();renderSchool();toast('Jenjang tersimpan.')}})}
function openClass(oldName=''){const meta=state.classMeta[oldName]||{};openModal({eyebrow:'DATA SEKOLAH',title:oldName?'Ubah Kelas':'Tambah Kelas',body:`<input type="hidden" id="fOriginal" value="${C.esc(oldName)}"><div class="field full"><label>Nama kelas</label><input id="fName" required value="${C.esc(oldName)}" placeholder="Contoh: Kelas 1 Putra"></div><div class="field"><label>Jenjang</label><select id="fLevel">${options(levelRows().map(x=>x.nama),meta.jenjang||C.inferLevel(oldName))}</select></div><div class="field"><label>Unit</label><select id="fUnit">${options(['Putra','Putri','Campuran'],meta.unit||(/putri/i.test(oldName)?'Putri':/putra/i.test(oldName)?'Putra':''))}</select></div>`,onSubmit:saveClass})}
async function saveClass(){const old=$('fOriginal').value.trim(),name=$('fName').value.trim(),meta={jenjang:$('fLevel').value,unit:$('fUnit').value,updatedAt:new Date().toISOString()};if(!name)throw new Error('Nama kelas wajib diisi.');if(name!==old&&allClassNames().some(x=>C.norm(x)===C.norm(name)))throw new Error('Kelas tersebut sudah ada.');const patch={[`${PATH.classMeta}/${safeKey(name)}`]:meta};if(old&&old!==name){patch[`${PATH.classes}/${safeKey(name)}`]=C.names(state.classes[old]);patch[`${PATH.classes}/${safeKey(old)}`]=null;patch[`${PATH.classMeta}/${safeKey(old)}`]=null;state.schedule.forEach(row=>{if(row.kelas===old){const id=safeKey(row._sourceKey||row.id||C.slug(`${row.hari}-${row.mapel}-${old}`));patch[`${PATH.schedule}/${id}/kelas`]=name}})}await update(ref(db),patch);if(old&&old!==name){state.classes[name]=state.classes[old]||[];delete state.classes[old];delete state.classMeta[old];state.schedule.forEach(r=>{if(r.kelas===old)r.kelas=name})}state.classMeta[name]=meta;closeModal();renderAll();toast('Kelas tersimpan dan referensi jadwal diselaraskan.')}
function openMembers(type,name){const source=type==='kelas'?state.classes:type==='usrah'?state.usrah:state.rooms,current=C.names(source[name]);openModal({eyebrow:type==='kelas'?'PESERTA KELAS':'ANGGOTA ASRAMA',title:`Atur ${name}`,save:'Simpan Anggota',body:`<div class="field full"><label>Satu nama per baris</label><textarea id="fMembers">${C.esc(current.join('\n'))}</textarea></div><div class="field full help">Gunakan ejaan nama yang sama dengan Data Santri. Perubahan ini langsung menjadi roster aktif.</div>`,onSubmit:async()=>{const list=[...new Set($('fMembers').value.split(/\n/).map(x=>x.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id')),path=type==='kelas'?PATH.classes:type==='usrah'?PATH.usrah:PATH.rooms,patch={[`${path}/${safeKey(name)}`]:list.length?list:null};if(type==='kelas')patch[`${PATH.classMeta}/${safeKey(name)}`]={...(state.classMeta[name]||{}),nama:name,updatedAt:new Date().toISOString()};if(type==='usrah')patch[`${PATH.usrahMeta}/${safeKey(name)}`]={nama:name,updatedAt:new Date().toISOString()};if(type==='kamar')patch[`${PATH.roomMeta}/${safeKey(name)}`]={nama:name,updatedAt:new Date().toISOString()};await update(ref(db),patch);source[name]=list;rebuildStudents();closeModal();renderAll();toast('Daftar anggota tersimpan.')}})}
function openGroup(type,oldName=''){const label=type==='usrah'?'Usrah / Halaqah':'Kamar';openModal({eyebrow:'DATA ASRAMA',title:oldName?`Ubah ${label}`:`Tambah ${label}`,body:`<input type="hidden" id="fOriginal" value="${C.esc(oldName)}"><div class="field full"><label>Nama ${label}</label><input id="fName" required value="${C.esc(oldName)}" placeholder="Contoh: ${type==='usrah'?'Usrah 1':'Kamar A1'}"></div>`,onSubmit:async()=>{const old=$('fOriginal').value.trim(),name=$('fName').value.trim(),source=type==='usrah'?state.usrah:state.rooms,meta=type==='usrah'?state.usrahMeta:state.roomMeta,path=type==='usrah'?PATH.usrah:PATH.rooms,metaPath=type==='usrah'?PATH.usrahMeta:PATH.roomMeta;if(!name)throw new Error(`Nama ${label} wajib diisi.`);if(name!==old&&[...Object.keys(source),...Object.keys(meta)].some(x=>C.norm(x)===C.norm(name)))throw new Error(`${label} tersebut sudah ada.`);const members=C.names(source[old]),patch={[`${metaPath}/${safeKey(name)}`]:{nama:name,updatedAt:new Date().toISOString()}};if(old&&old!==name){patch[`${path}/${safeKey(old)}`]=null;patch[`${metaPath}/${safeKey(old)}`]=null;if(members.length)patch[`${path}/${safeKey(name)}`]=members}await update(ref(db),patch);if(old&&old!==name){delete source[old];delete meta[old]}source[name]=members;meta[name]={nama:name};closeModal();renderDorm();toast(`${label} tersimpan.`)}})}
const DAYS=['senin','selasa','rabu','kamis','jumat','sabtu','ahad'];function openProgram(p={}){openModal({eyebrow:'PROGRAM ASRAMA',title:p.nama?'Ubah Program':'Tambah Program',body:`<input id="fProgramId" type="hidden" value="${C.esc(p.id||'')}"><input id="fProgramPath" type="hidden" value="${C.esc(p.sourcePath||'')}"><div class="field full"><label>Nama program</label><input id="fName" required value="${C.esc(p.nama||'')}"></div><div class="field"><label>Kategori</label><input id="fCategory" value="${C.esc(p.kategori||'Program Asrama')}"></div><div class="field"><label>Urutan</label><input id="fOrder" type="number" min="1" value="${C.esc(p.urutan===999?'':p.urutan||'')}"></div><div class="field"><label>Jam mulai</label><input id="fStart" type="time" value="${C.esc(p.mulai||'')}"></div><div class="field"><label>Jam selesai</label><input id="fEnd" type="time" value="${C.esc(p.selesai||'')}"></div><div class="field full"><label>Hari aktif (kosong = setiap hari)</label><div class="check-row">${DAYS.map(d=>`<label class="check"><input type="checkbox" name="days" value="${d}" ${p.hariAktif?.includes(d)?'checked':''}> ${d[0].toUpperCase()+d.slice(1)}</label>`).join('')}</div></div><div class="field full"><div class="check-row"><label class="check"><input id="fActive" type="checkbox" ${p.aktif!==false?'checked':''}> Program aktif</label><label class="check"><input id="fAttendance" type="checkbox" ${p.wajibAbsen!==false?'checked':''}> Wajib diabsen</label><label class="check"><input id="fReport" type="checkbox" ${p.wajibLaporan===true?'checked':''}> Wajib dilaporkan</label></div></div>`,onSubmit:saveProgram})}
async function saveProgram(){const oldId=$('fProgramId').value,id=oldId||C.slug($('fName').value),oldPath=$('fProgramPath').value,data={id,nama:$('fName').value.trim(),kategori:$('fCategory').value.trim()||'Program Asrama',mulai:$('fStart').value,selesai:$('fEnd').value,hariAktif:[...document.querySelectorAll('input[name="days"]:checked')].map(x=>x.value),wajibAbsen:$('fAttendance').checked,wajibLaporan:$('fReport').checked,aktif:$('fActive').checked,urutan:Number($('fOrder').value)||999,updatedAt:new Date().toISOString()};if(!data.nama)throw new Error('Nama program wajib diisi.');const canonical=`${PATH.program}/${safeKey(id)}`,patch={[canonical]:data};if(oldPath&&oldPath!==canonical.replace(`${PATH.program}/`,''))patch[`${PATH.program}/${oldPath}`]=null;await update(ref(db),patch);closeModal();await reloadPrograms();toast('Jadwal program tersimpan.')}
async function reloadPrograms(){const [program,master]=await Promise.all([get(ref(db,PATH.program)),get(ref(db,PATH.programMaster))]);state.programRaw=program.val()||{};state.programMasterRaw=master.val()||{};resolvePrograms();renderPrograms()}
async function removeGroup(type,name){const source=type==='usrah'?state.usrah:state.rooms,meta=type==='usrah'?state.usrahMeta:state.roomMeta,path=type==='usrah'?PATH.usrah:PATH.rooms,metaPath=type==='usrah'?PATH.usrahMeta:PATH.roomMeta;if(C.names(source[name]).length)return toast('Pindahkan seluruh anggota sebelum menghapus kelompok.','error');if(!confirm(`Hapus ${name}?`))return;await update(ref(db),{[`${path}/${safeKey(name)}`]:null,[`${metaPath}/${safeKey(name)}`]:null});delete source[name];delete meta[name];renderDorm();toast('Kelompok dihapus.')}
document.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target)return;try{if(target.dataset.view)return showView(target.dataset.view,true);if(target.dataset.open)return location.href=target.dataset.open;if(target.matches('[data-close]'))return closeModal();if(target.dataset.downloadGroup||target.dataset.downloadClass)return downloadSchedule({group:target.dataset.downloadGroup||'',kelas:target.dataset.downloadClass||'',button:target});if(target.id==='downloadSchedule')return downloadSchedule({button:target});if(target.id==='refreshBtn'||target.id==='overviewRefresh')return loadAll();if(target.id==='saveFeatureRole')return saveFeatureRole();if(target.id==='resetFeatureRole'){state.featureDraft=new Set([...defaultFeaturesForRole($('featureRole').value),...lockedFeatureIds($('featureRole').value)]);state.featureReset=true;renderFeatures();return}if(target.id==='enableVisibleFeatures'||target.id==='disableVisibleFeatures'){const enable=target.id==='enableVisibleFeatures';featureRowsVisible().forEach(item=>{if(enable)state.featureDraft.add(item.id);else if(!lockedFeatureIds($('featureRole').value).includes(item.id))state.featureDraft.delete(item.id)});state.featureReset=false;renderFeatures();return}if(target.id==='addStudent')return openStudent();if(target.id==='addLevel')return openLevel();if(target.id==='addClass')return openClass();if(target.id==='addProgram')return openProgram();if(target.dataset.addGroup)return openGroup(target.dataset.addGroup);if(target.dataset.editStudent)return openStudent(state.students.find(x=>x.studentKey===target.dataset.editStudent));if(target.dataset.deleteStudent)return deleteStudent(state.students.find(x=>x.studentKey===target.dataset.deleteStudent));if(target.dataset.editLevel)return openLevel(levelRows().find(x=>x.id===target.dataset.editLevel));if(target.dataset.deleteLevel){const item=levelRows().find(x=>x.id===target.dataset.deleteLevel);if(confirm(`Hapus jenjang ${item.nama}? Kelas tidak ikut dihapus.`)){await remove(ref(db,`${PATH.levels}/${safeKey(item.id)}`));delete state.levels[item.id];renderSchool()}return}if(target.dataset.editClass!==undefined)return openClass(target.dataset.editClass);if(target.dataset.deleteClass!==undefined){const name=target.dataset.deleteClass;if(C.names(state.classes[name]).length)return toast('Pindahkan peserta sebelum menghapus kelas.','error');if(confirm(`Hapus kelas ${name}?`)){await update(ref(db),{[`${PATH.classes}/${safeKey(name)}`]:null,[`${PATH.classMeta}/${safeKey(name)}`]:null});delete state.classes[name];delete state.classMeta[name];renderSchool()}return}if(target.dataset.members)return openMembers(target.dataset.members,target.dataset.group);if(target.dataset.editGroup)return openGroup(target.dataset.editGroup,target.dataset.group);if(target.dataset.deleteGroup)return removeGroup(target.dataset.deleteGroup,target.dataset.group);if(target.dataset.editProgram)return openProgram(state.programs.find(x=>x.id===target.dataset.editProgram));if(target.dataset.deleteProgram){const p=state.programs.find(x=>x.id===target.dataset.deleteProgram);if(confirm(`${p.hasFallback?'Nonaktifkan':'Hapus'} program ${p.nama}? Riwayat absensi tidak ikut dihapus.`)){if(p.hasFallback){const data={id:p.id,nama:p.nama,kategori:p.kategori,mulai:p.mulai,selesai:p.selesai,hariAktif:p.hariAktif||[],wajibAbsen:false,wajibLaporan:false,aktif:false,urutan:p.urutan,updatedAt:new Date().toISOString()};await set(ref(db,`${PATH.program}/${safeKey(p.id)}`),data)}else await remove(ref(db,`${PATH.program}/${p.sourcePath||safeKey(p.id)}`));await reloadPrograms();toast(p.hasFallback?'Program dinonaktifkan.':'Program dihapus.')}return}}catch(error){console.error(error);toast(error.message||String(error),'error')}});
$('modalForm').addEventListener('submit',async event=>{event.preventDefault();if(!submitAction)return;$('modalSave').disabled=true;try{await submitAction()}catch(error){console.error(error);toast(error.message||String(error),'error')}finally{$('modalSave').disabled=false}});$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});$('scheduleSearch').addEventListener('input',renderSchedule);$('scheduleClass').addEventListener('change',renderSchedule);$('studentSearch').addEventListener('input',renderStudents);$('staffSearch').addEventListener('input',renderStaff);$('programSearch').addEventListener('input',renderPrograms);$('featureSearch').addEventListener('input',renderFeatures);$('featureRole').addEventListener('change',loadFeatureDraft);$('featureList').addEventListener('change',event=>{const input=event.target.closest('[data-feature-id]');if(!input)return;if(input.checked)state.featureDraft.add(input.dataset.featureId);else state.featureDraft.delete(input.dataset.featureId);state.featureReset=false;renderFeatures()});showView(currentView());loadAll();
